#!/usr/bin/env bash
# Drift check for the model entitlement refusal golden (WS10-S1).
#
# apps/Model Plane/api/contracts/model-entitlement-refusals.json is generated by mp-contracts
# (model_entitlement::catalogue_json, never written by hand) and read by the SPA, which renders each
# code in Norwegian and English. This script closes three ways it can silently break:
#
#   * the golden must hash to the digest pinned below, and agree with the .sha256 beside it, so
#     changing the contract is a deliberate second step (regenerate with
#     MP_UPDATE_GOLDEN=1 cargo test -p mp-contracts --test model_entitlement_catalogue, then
#     update the .sha256 and the pin here, in the same change);
#   * the SPA's vendored copy of the golden and of its pin must be byte-identical to the originals;
#   * the strict loader (scripts/tests/model-entitlement-contract-schema.mjs) must accept it: no
#     unknown field, only the two codes and five reasons, a body that is content-free, and
#     agreement with the entitlement matrix.
#
# A missing file is a failure, never a skip. Goldens are LF files (.gitattributes pins *.json to
# eol=lf), hashed byte for byte. The ZDR drift check (zdr-contract-sync.test.sh) is separate and
# untouched: the two vocabularies do not share a file.
#
# Usage:
#   scripts/tests/model-entitlement-contract-sync.test.sh              run the checks
#   scripts/tests/model-entitlement-contract-sync.test.sh --self-test  prove the checks fail on a tampered golden
set -Eeuo pipefail

SELF="${BASH_SOURCE[0]}"
SCRIPT_DIR="$(cd "$(dirname "$SELF")" && pwd)"
# CONTRACT_SYNC_ROOT lets the self-test point the same checks at a scratch tree.
ROOT="${CONTRACT_SYNC_ROOT:-$(cd "$SCRIPT_DIR/../.." && pwd)}"

REFUSALS="apps/Model Plane/api/contracts/model-entitlement-refusals.json"
REFUSALS_SHA256="d8b48550661ed4daefcff792707c9e1d241b7ddd9ac9f05e8aa64bbcd85a647a"
# Vendored copies, "<copy>|<golden it vendors>": the SPA reads its own byte-identical copy and pin
# (its test reads nothing outside its tree), so a drifted copy fails here.
SPA_CONTRACTS="apps/Frontend Plane/verevonv3/src/shared/api/contracts"
VENDORED=(
  "$SPA_CONTRACTS/model-entitlement-refusals.json|$REFUSALS"
  "$SPA_CONTRACTS/model-entitlement-refusals.json.sha256|$REFUSALS.sha256"
)
# The matrix the loader checks the refusal rows against. Authored, vendored byte for byte into
# org-core by its own test, so it is only read here.
MATRIX="apps/Model Plane/api/contracts/model-entitlement-matrix.json"

passes=0
failures=0
pass() { printf 'ok - %s\n' "$1"; passes=$((passes + 1)); }
fail() { printf 'not ok - %s\n' "$1" >&2; failures=$((failures + 1)); }

sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | cut -d' ' -f1
  else
    shasum -a 256 "$1" | cut -d' ' -f1
  fi
}

has_carriage_return() { [[ -n "$(tr -d '\n' <"$1" | tr -cd '\r')" ]]; }

# Node on Windows cannot read a Cygwin path; everywhere else this is the identity.
to_native() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -w "$1"; else printf '%s' "$1"; fi
}

check_golden() {
  local actual sibling
  if [[ ! -f "$ROOT/$REFUSALS" ]]; then
    fail "golden is missing: $REFUSALS"
    return 0
  fi
  if has_carriage_return "$ROOT/$REFUSALS"; then
    fail "golden has CR line endings (it is hashed byte for byte, LF only): $REFUSALS"
    return 0
  fi
  actual="$(sha256_of "$ROOT/$REFUSALS")"
  if [[ "$actual" != "$REFUSALS_SHA256" ]]; then
    fail "golden differs from its pinned digest: $REFUSALS
    pinned   $REFUSALS_SHA256
    actual   $actual
    If the change is intended, regenerate it with MP_UPDATE_GOLDEN=1 cargo test -p mp-contracts --test model_entitlement_catalogue and update the .sha256 beside it and the pin in $(basename "$SELF")."
    return 0
  fi
  pass "golden matches its pinned digest: $REFUSALS"
  if [[ ! -f "$ROOT/$REFUSALS.sha256" ]]; then
    fail "pin file is missing: $REFUSALS.sha256"
    return 0
  fi
  sibling=""
  read -r sibling _ <"$ROOT/$REFUSALS.sha256" || true
  if [[ "$sibling" == "$REFUSALS_SHA256" ]]; then
    pass "pin file beside the golden agrees: $REFUSALS.sha256"
  else
    fail "pin file beside the golden disagrees with the pinned digest: $REFUSALS.sha256 says '$sibling', expected $REFUSALS_SHA256"
  fi
}

check_vendored() {
  local row copy golden
  for row in "${VENDORED[@]}"; do
    copy="${row%%|*}"
    golden="${row##*|}"
    if [[ ! -f "$ROOT/$copy" ]]; then
      fail "vendored copy is missing: $copy"
    elif [[ ! -f "$ROOT/$golden" ]]; then
      fail "the golden a copy vendors is missing: $golden (copy: $copy)"
    elif cmp -s "$ROOT/$copy" "$ROOT/$golden"; then
      pass "vendored copy is byte-identical to its golden: $copy"
    else
      fail "vendored copy differs from its golden: $copy (golden: $golden)"
    fi
  done
}

check_schema() {
  local out
  if ! command -v node >/dev/null 2>&1; then
    fail "node is required to check the entitlement refusal golden (scripts/tests/model-entitlement-contract-schema.mjs); a check that cannot run is a failure"
    return 0
  fi
  if out="$(node "$(to_native "$SCRIPT_DIR/model-entitlement-contract-schema.mjs")" "$(to_native "$ROOT")" 2>&1)"; then
    pass "entitlement refusal golden loads strictly, is content-free and agrees with the matrix (model-entitlement-contract-schema.mjs)"
  else
    fail "entitlement refusal golden is malformed or inconsistent (model-entitlement-contract-schema.mjs):
$out"
  fi
}

# The check is only worth having if it can fail. Copy the golden, its pin and the matrix into a
# scratch tree, require the checks to accept the untouched copy, then flip one byte and require
# them to reject it; then require the strict loader to reject a malformed golden on its own, with
# no pin in the way.
self_test() {
  local path row
  SCRATCH="$(mktemp -d)"
  trap 'rm -rf "$SCRATCH"' EXIT
  for path in "$REFUSALS" "$REFUSALS.sha256" "$MATRIX" "${VENDORED[0]%%|*}" "${VENDORED[1]%%|*}"; do
    mkdir -p "$SCRATCH/$(dirname "$path")"
    cp "$ROOT/$path" "$SCRATCH/$path"
  done
  if ! CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SELF" >/dev/null 2>&1; then
    echo "self-test: the checks reject an untouched copy of the golden" >&2
    return 1
  fi
  printf ' ' >>"$SCRATCH/$REFUSALS"
  if CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SELF" >/dev/null 2>&1; then
    echo "self-test: the checks accept a tampered golden" >&2
    return 1
  fi
  cp "$ROOT/$REFUSALS" "$SCRATCH/$REFUSALS"
  # A vendored copy that drifted must fail with the golden itself intact.
  path="${VENDORED[0]%%|*}"
  printf ' ' >>"$SCRATCH/$path"
  if CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SELF" >/dev/null 2>&1; then
    echo "self-test: the checks accept a vendored copy that differs from its golden" >&2
    return 1
  fi
  cp "$ROOT/$path" "$SCRATCH/$path"
  # A pin file that disagrees must fail with the golden itself intact.
  printf '%064d *model-entitlement-refusals.json\n' 0 >"$SCRATCH/$REFUSALS.sha256"
  if CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SELF" >/dev/null 2>&1; then
    echo "self-test: the checks accept a pin file that disagrees with the pinned digest" >&2
    return 1
  fi
  cp "$ROOT/$REFUSALS.sha256" "$SCRATCH/$REFUSALS.sha256"
  if ! command -v node >/dev/null 2>&1; then
    echo "self-test: node is required (scripts/tests/model-entitlement-contract-schema.mjs)" >&2
    return 1
  fi
  node -e 'const fs=require("fs");const p=process.argv[1];const d=JSON.parse(fs.readFileSync(p,"utf8"));d.wire.details.push("prompt");fs.writeFileSync(p,JSON.stringify(d,null,2)+"\n")' "$(to_native "$SCRATCH/$REFUSALS")"
  if node "$(to_native "$SCRIPT_DIR/model-entitlement-contract-schema.mjs")" "$(to_native "$SCRATCH")" >/dev/null 2>&1; then
    echo "self-test: the strict loader accepts a refusal body that carries content" >&2
    return 1
  fi
  echo "self-test ok: an untouched copy passes, a tampered golden fails, a drifted vendored copy fails, a disagreeing pin fails, a content-carrying golden fails the strict loader"
}

if [[ "${1:-}" == "--self-test" ]]; then
  self_test
  exit $?
fi

check_golden
check_vendored
check_schema
printf '%s passed, %s failed\n' "$passes" "$failures"
[[ "$failures" -eq 0 ]]
